    async update(id,patch) {
      return _withMutationLock('orders.update:'+String(id||''), async ()=>{
        const o=(_d.orders||[]).find(x=>x.id===id); if(!o)return null;
        if(_dbOk) {
          const r=await _api('orders.update',{id,patch});
          if(!r.ok) throw new Error(r.message || r.error || 'orders_update_failed');
        }
        Object.assign(o,patch);
        if('masterId'in patch){
          const nextMasterId = (patch.masterId === 0 || patch.masterId === '0' || patch.masterId === '' || patch.masterId == null) ? '0' : patch.masterId;
          const nextMaster = nextMasterId!=='0' ? ((_d.masters||[]).find(m=>m.id===nextMasterId)||null) : null;
          o.masterId = nextMasterId;
          o.masterName = nextMaster ? nextMaster.name : 'Администрация';
          const chat = (_d.chats||[]).find(c=>c.orderId===id || c.id===o.chatId);
          if(chat){
            chat.masterId = nextMasterId;
            chat.masterName = nextMaster ? nextMaster.name : 'Администрация';
            chat.masterInit = nextMaster ? (nextMaster.initials || (nextMaster.name||'').split(' ').map(w=>w[0]||'').slice(0,2).join('').toUpperCase()) : 'А';
          }
        }
        if('assignedAdminUserId' in patch){
          o.assignedAdminUserId = patch.assignedAdminUserId == null || patch.assignedAdminUserId === '' ? null : Number(patch.assignedAdminUserId);
          const chat = (_d.chats||[]).find(c=>c.orderId===id || c.id===o.chatId);
          if(chat) chat.assignedAdminUserId = o.assignedAdminUserId;
        }
        _save('orders.change');
        return o;
      });
    },


