    // ── Биржа заявок ─────────────────────────────────────────────────────
    // Мастер берёт свободную заявку из биржи
    async masterClaim(id) {
      return _withMutationLock('orders.masterClaim:'+String(id||''), async () => {
        const o = (_d.orders||[]).find(x => x.id === id);
        if (!o) return null;
        // Локальная проверка — заявка ещё свободна?
        if (String(o.masterId||'0') !== '0') throw new Error('already_taken');
        if (!['new','waiting_responses'].includes(String(o.status||''))) throw new Error('order_not_available');
        if (_dbOk) {
          const r = await _api('orders.masterClaim', {id});
          if (!r.ok) throw new Error(r.message || r.error || 'master_claim_failed');
          if (r.order) Object.assign(o, r.order);
          else o.status = 'process';
          if (r.chat) {
            if(!_d.chats) _d.chats=[];
            const chatExisting = (_d.chats||[]).find(c => c.orderId === id || c.id === r.chat.id || c.id === o.chatId);
            if (chatExisting) Object.assign(chatExisting, r.chat);
            else _d.chats.push(r.chat);
            o.chatId = r.chat.id || o.chatId;
            o.chat = r.chat;
          }
          const chat = (_d.chats||[]).find(c => c.orderId === id || c.id === o.chatId);
          if (chat) {
            chat.status = o.status || 'process';
            if (r.chat) Object.assign(chat, r.chat);
          }
          if(Array.isArray(_d.orderEvents)) _d.orderEvents.push({id:'ev_'+Date.now(), orderId:id, type:'master_accepted', label:'Мастер принял заявку', createdAt:new Date().toISOString()});
          _save('orders.masterClaim');
          return o;
        }
        // offline fallback: optimistic update
        const u = window._appState?.user;
        o.masterId = 'local_' + String(u?.id||'me');
        o.masterName = u?.name || 'Мастер';
        o.status = 'process';
        o.acceptedAt = new Date().toISOString();
        const chatId = o.chatId || ('ch_' + String(o.id||id).replace(/[^a-zA-Z0-9_-]/g,'_'));
        o.chatId = chatId;
        if(!_d.chats) _d.chats=[];
        if(!(_d.chats||[]).some(c=>String(c.id)===String(chatId))) _d.chats.push({id:chatId, orderId:id, clientName:o.clientName||'Клиент', clientPhone:o.clientPhone||'', masterId:o.masterId, masterName:o.masterName, orderTitle:o.serviceNames||o.notes||'Заявка', car:o.clientCar||'', status:o.status, unread:{client:1,master:0,admin:0}, updatedAt:new Date().toISOString()});
        if(!_d.messages) _d.messages={};
        if(!_d.messages[chatId]) _d.messages[chatId]=[];
        _d.messages[chatId].push({id:'m_accept_'+Date.now(), from:'system', type:'event', text:'Мастер принял заявку. Чат открыт для согласования.', time:_nowStr(), createdAt:new Date().toISOString()});
        if(Array.isArray(_d.orderEvents)) _d.orderEvents.push({id:'ev_'+Date.now(), orderId:id, type:'master_accepted', label:'Мастер принял заявку', createdAt:new Date().toISOString()});
        _save('orders.masterClaim');
        return o;
      });
    },

