  let _clientsRefreshPromise = null;
  let _clientsRefreshAt = 0;
  let _clientsRefreshQ = '';

  const Clients = {
    getAll(q){
      let list=(_d.clients||[]).slice();
      // Дополняем клиентами из users (для admin: _d.users уже включает всех после pull)
      (_d.users||[]).forEach(u=>{
        if(!list.find(c=>(c.phone||'').replace(/\D/g,'') === (u.phone||'').replace(/\D/g,''))){
          list.push({id:'u_'+u.phone,phone:u.phone,name:u.name||'',car:u.car||'',
            initials:u.initials||'',role:u.role||'client',active:u.active!==false,
            ordersCount:0,totalSpent:0,createdAt:''});
        }
      });
      if(q){const ql=q.toLowerCase();list=list.filter(c=>(c.name||'').toLowerCase().includes(ql)||(c.phone||'').includes(ql)||(c.car||'').toLowerCase().includes(ql));}
      return list.sort((a,b)=>(b.ordersCount||0)-(a.ordersCount||0));
    },
    get(id){return(_d.clients||[]).find(c=>c.id===id)||null;},
    getByPhone(phone){const p=(phone||'').replace(/\D/g,'');return(_d.clients||[]).find(c=>(c.phone||'').replace(/\D/g,'')===p)||null;},
    getOrders(id){ _syncOrderChatLinks(); return (_d.orders||[]).filter(o=>o.clientId===id).map(_normalizeOrderRecord);},
    async create(data){
      if(data.phone&&Clients.getByPhone(data.phone))return Clients.getByPhone(data.phone);
      const draft={id:'cl_'+Date.now().toString(36),name:data.name||'',phone:data.phone||'',car:data.car||'',notes:'',createdAt:new Date().toISOString().split('T')[0],ordersCount:0,totalSpent:0};
      if(_dbOk) {
        const r=await _api('clients.upsert',{client:{...draft}});
        if(!r.ok) throw new Error(r.message || r.error || 'clients_upsert_failed');
        if(r.id) draft.id = r.id;
      }
      if(!_d.clients)_d.clients=[];
      _d.clients.push(draft);_save('clients.create');
      return draft;
    },
    async update(id,patch){
      const c=(_d.clients||[]).find(x=>x.id===id);if(!c)return null;
      if(_dbOk) {
        const r=await _api('clients.update',{id,patch});
        if(!r.ok) throw new Error(r.message || r.error || 'clients_update_failed');
      }
      Object.assign(c,patch);_save('clients.change');
      return c;
    },
    // Принудительно обновить список клиентов с сервера (для admin/owner панели)
    async refreshFromServer(q){
      if(!_dbOk) return (_d.clients||[]);
      const nextQ = String(q||'');
      const now = Date.now();
      if (_clientsRefreshPromise && _clientsRefreshQ === nextQ) return _clientsRefreshPromise;
      if (_clientsRefreshQ === nextQ && (now - _clientsRefreshAt) < 12000) return (_d.clients||[]);
      _clientsRefreshQ = nextQ;
      _clientsRefreshAt = now;
      _clientsRefreshPromise = _api('clients.getAll',{q:nextQ})
        .then(r=>{
          if(r.ok && Array.isArray(r.clients)){
            const incoming=r.clients;
            incoming.forEach(c=>{ const idx=(_d.clients||[]).findIndex(x=>x.id===c.id); if(idx>=0) Object.assign(_d.clients[idx],c); else {if(!_d.clients)_d.clients=[];_d.clients.push(c);} });
            _save('clients.refreshed');
          }
          return (_d.clients||[]);
        })
        .finally(()=>{ _clientsRefreshPromise = null; });
      return _clientsRefreshPromise;
    },
  };

