  function _normalizeShopPartPayload(pd){
    pd = pd && typeof pd === 'object' ? pd : {};
    const analogs = Array.isArray(pd.analogs) ? pd.analogs.join(' · ') : (pd.analogs || pd.analogsText || pd.analogs_json || '');
    const crosses = Array.isArray(pd.crosses)
      ? pd.crosses.map(x => (x && typeof x === 'object') ? [x.brand, x.number || x.label, x.tier].filter(Boolean).join(':') : String(x||'')).join('\n')
      : (pd.crosses || pd.crossesText || pd.crosses_json || pd.crossNumbers || '');
    const suppliers = Array.isArray(pd.suppliers)
      ? pd.suppliers.map(x => (x && typeof x === 'object') ? [x.supplier || x.name, x.price || x.priceLabel, x.eta || x.delivery, x.stockQty || x.stock, x.city].filter(Boolean).join(' | ') : String(x||'')).join('\n')
      : (pd.suppliers || pd.suppliersText || pd.suppliers_json || pd.offers || '');
    const fitments = Array.isArray(pd.fitments)
      ? pd.fitments.map(x => (x && typeof x === 'object') ? [x.make || x.vehicleMake, x.model || x.vehicleModel, x.generation || x.vehicleGeneration, ((x.yearFrom||x.year_to||x.yearTo) ? `${x.yearFrom || ''}-${x.yearTo || ''}` : ''), x.engine, x.body, Array.isArray(x.vinPrefixes) ? x.vinPrefixes.join(',') : (x.vinPrefixes || x.vin_prefixes)].filter(Boolean).join(' | ') : String(x||'')).join('\n')
      : (pd.fitments || pd.fitmentsText || pd.fitments_json || pd.vehicleFitments || '');
    return {
      id:pd.id || '',
      name:String(pd.name || pd.title || '').trim(),
      sku:String(pd.sku || pd.article || pd.partNumber || '').trim(),
      cat:String(pd.cat || pd.category || 'other').trim() || 'other',
      price:Number(String(pd.price || pd.priceRaw || '').replace(/[^0-9]/g,'')) || 0,
      stock:pd.stock !== false,
      stockQty:Number(pd.stockQty ?? pd.qty ?? pd.count ?? 0) || 0,
      note:String(pd.note || '').trim(),
      img:String(pd.img || pd.image || pd.imageUrl || '').trim(),
      image:String(pd.image || pd.img || pd.imageUrl || '').trim(),
      brand:String(pd.brand || pd.manufacturer || pd.maker || '').trim(),
      manufacturer:String(pd.manufacturer || pd.brand || pd.maker || '').trim(),
      manufacturerType:String(pd.manufacturerType || pd.manufacturer_type || pd.type || '').trim(),
      oem:String(pd.oem || pd.oemNumber || pd.oem_number || '').trim(),
      analogs:String(analogs || '').trim(),
      analogsText:String(analogs || '').trim(),
      crosses:String(crosses || '').trim(),
      crossesText:String(crosses || '').trim(),
      suppliers:String(suppliers || '').trim(),
      suppliersText:String(suppliers || '').trim(),
      fitments:String(fitments || '').trim(),
      fitmentsText:String(fitments || '').trim(),
      compatibility:String(pd.compatibility || pd.fitment || pd.models || '').trim(),
      vehicleMake:String(pd.vehicleMake || pd.vehicle_make || pd.make || '').trim(),
      vehicleModel:String(pd.vehicleModel || pd.vehicle_model || pd.model || '').trim(),
      vehicleGeneration:String(pd.vehicleGeneration || pd.vehicle_generation || pd.generation || '').trim(),
      yearFrom:Number(pd.yearFrom ?? pd.year_from ?? 0) || '',
      yearTo:Number(pd.yearTo ?? pd.year_to ?? 0) || '',
      engine:String(pd.engine || '').trim(),
      body:String(pd.body || '').trim(),
      vinPrefixes:Array.isArray(pd.vinPrefixes) ? pd.vinPrefixes.join(' · ') : String(pd.vinPrefixes || pd.vin_prefixes || '').trim(),
      description:String(pd.description || pd.desc || '').trim()
    };
  }

