  async function reset(force=false){
    if (_pullInflight) {
      try { await _pullInflight; return _d; } catch(_e) {}
    }
    if(!force && _lastSuccessfulPullAt && (Date.now() - _lastSuccessfulPullAt) < 8000){
      return _d;
    }
    if(_dbOk){
      try {
        _pullInflight = (async () => {
          const res = await fetch(API + '?action=pul', { credentials:'same-origin', cache:'no-store' });
          const json = await res.json().catch(()=>({ok:false,error:'invalid_json'}));
          if ([401,403,409].includes(res.status)) {
            _dwarnDebug('[DB] reset pull deferred until identity is consistent', {status:res.status,error:json?.error||''});
            return false;
          }
          if(json.ok && json.data){
            _d = json.data;
            _ensureCollections();
        _ensureCollections();
            if (Array.isArray(json.users)) _d.users = json.users.slice();
            if (json._debug) _dwarnDebug('[DB] reset _debug:', JSON.parse(JSON.stringify(json._debug)));
            _dlog('[DB] reset pull OK, masters:', (_d?.masters||[]).length);
            _lastSuccessfulPullAt = Date.now();
            _save('db.reset.pull');
            return true;
          }
          console.warn('[DB] reset pull json.ok=false', json);
          return false;
        })();
        const ok = await _pullInflight;
        if (ok) return _d;
      } catch(e){ console.error('[DB] reset pull exception', e); }
      finally { _pullInflight = null; }
    }
    _d=JSON.parse(JSON.stringify(SEED)); _save('db.reset.local');
    return _d;
  }

